import sys
import requests
import toml
from bs4 import BeautifulSoup
from datetime import datetime
import logging
from typing import List, Dict, Optional

def parse_feed_entries(feed_html: str, feed_type: str) -> List[Dict]:
    soup = BeautifulSoup(feed_html, 'xml')
    entries = []

    if feed_type == 'rss':
        items = soup.find_all('item')
    elif feed_type == 'atom':
        items = soup.find_all('entry')
    else:
        return entries

    for item in items:
        title = item.find('title').get_text(strip=True) if item.find('title') else ''
        pub_date = item.find('pubDate').get_text(strip=True) if item.find('pubDate') else ''
        updated = item.find('updated').get_text(strip=True) if item.find('updated') else ''
        timestamp = pub_date if pub_date else updated

        entries.append({
            'title': title,
            'timestamp': timestamp
        })

    return entries

def get_newest_entry(entries: List[Dict]) -> Optional[str]:
    if not entries:
        return ''

    try:
        newest = max(entries, key=lambda x: datetime.strptime(x['timestamp'], '%a, %d %b %Y %H:%M:%S %z') if x['timestamp'] else datetime.min)
        return newest['title']
    except (ValueError, TypeError):
        return ''

def process_feed(name: str, url: str) -> int:
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        feed_type = url.split('.')[-2].lower() if '.' in url else 'unknown'
        entries = parse_feed_entries(response.text, feed_type)
        entry_count = len(entries)
        newest_title = get_newest_entry(entries)

        return entry_count, newest_title
    except Exception as e:
        error_msg = str(e).replace('\n', ' ')
        return 0, '', error_msg

def main():
    if len(sys.argv) != 2:
        print("Usage: python feedwatch.py <config-path>")
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = toml.load(f)
    except Exception as e:
        print(f"Error reading config: {e}")
        sys.exit(1)

    feeds = config.get('feeds', [])
    if not isinstance(feeds, list):
        print("Error: 'feeds' must be a list in the config")
        sys.exit(1)

    logging.basicConfig(
        filename='feedwatch.log',
        level=logging.INFO,
        format='%(levelname)s %(name)s %(message)s'
    )

    success = True
    for feed in feeds:
        if not isinstance(feed, dict) or 'name' not in feed or 'url' not in feed:
            continue

        name = feed['name']
        url = feed['url']
        entry_count, newest_title, error_msg = process_feed(name, url)

        if error_msg:
            logging.error(f"{name} {url} {error_msg}")
            success = False
        else:
            logging.info(f"{name} {url} {entry_count}")

        print(f"{name}\t{entry_count}\t{newest_title}")

    sys.exit(0 if success else 1)

if __name__ == "__main__":
    main()
